 84→    // App name from base
 85→    assert_eq!(config.app_name, Some("BaseApp".to_string()));
 86→
 87→    // Setting overridden by local
 88→    assert_eq!(config.settings.default_output, OutputMode::Quiet);
 89→
 90→    // Step command overridden by local
 91→    assert_eq!(
 92→        config.steps["deps"].command,
 93→        Some("yarn install --frozen-lockfile".to_string())
 94→    );
 95→}
