146→/// Summary of a workflow run, used by `show_run_summary`.
147→#[derive(Debug, Clone)]
148→pub struct RunSummary {
149→    /// Per-step results in execution order.
150→    pub step_results: Vec<StepSummary>,
151→    /// Total run duration.
152→    pub total_duration: Duration,
153→    /// Number of steps that ran.
154→    pub steps_run: usize,
155→    /// Number of steps skipped.
156→    pub steps_skipped: usize,
157→    /// Whether all steps succeeded.
158→    pub success: bool,
159→    /// Names of failed steps.
160→    pub failed_steps: Vec<String>,
161→}
