//! Human-readable output formatter.
//!
//! Formats lint diagnostics for terminal display with optional color support.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output for human consumption.
pub struct HumanFormatter {
    /// Whether to use colors (ANSI escape codes).
    pub use_color: bool,
}

impl HumanFormatter {
    /// Create a new human formatter.
    pub fn new(use_color: bool) -> Self {
        Self { use_color }
    }

    fn severity_prefix(&self, severity: Severity) -> &'static str {
        match severity {
            Severity::Hint => "hint",
            Severity::Warning => "warning",
            Severity::Error => "error",
        }
    }
}

impl LintFormatter for HumanFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            // Header line: error[rule-id]: message
            writeln!(
                writer,
                "{}[{}]: {}",
                self.severity_prefix(diag.severity),
                diag.rule_id.0,
                diag.message
            )?;

            // Location line
            if let Some(ref span) = diag.span {
                writeln!(
                    writer,
                    "  --> {}:{}:{}",
                    span.file.display(),
                    span.start_line,
                    span.start_col
                )?;
            }

            // Suggestion
            if let Some(ref suggestion) = diag.suggestion {
                writeln!(writer, "   = help: {}", suggestion)?;
            }

            // Related info
            for related in &diag.related {
                writeln!(
                    writer,
                    "   = note: {} ({}:{})",
                    related.message,
                    related.span.file.display(),
                    related.span.start_line
                )?;
            }

            writeln!(writer)?;
        }

        // Summary
        let error_count = diagnostics
            .iter()
            .filter(|d| d.severity == Severity::Error)
            .count();
        let warning_count = diagnostics
            .iter()
            .filter(|d| d.severity == Severity::Warning)
            .count();

        if error_count > 0 || warning_count > 0 {
            writeln!(
                writer,
                "Found {} error(s) and {} warning(s)",
                error_count, warning_count
            )?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_diagnostic() {
        let formatter = HumanFormatter::new(false);
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Test error message",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("error[test-rule]"));
        assert!(output.contains("Test error message"));
        assert!(output.contains("config.yml:10"));
    }

    #[test]
    fn formats_warning_diagnostic() {
        let formatter = HumanFormatter::new(false);
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Warning,
            "Test warning message",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("warning[test-rule]"));
    }

    #[test]
    fn formats_hint_diagnostic() {
        let formatter = HumanFormatter::new(false);
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Hint,
            "Test hint message",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("hint[test-rule]"));
    }

    #[test]
    fn formats_summary_line() {
        let formatter = HumanFormatter::new(false);
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "err"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warn"),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Warning, "warn2"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("1 error(s)"));
        assert!(output.contains("2 warning(s)"));
    }

    #[test]
    fn formats_suggestion() {
        let formatter = HumanFormatter::new(false);
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test-rule"), Severity::Warning, "Test message")
                    .with_suggestion("Try this instead"),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("= help: Try this instead"));
    }

    #[test]
    fn formats_related_info() {
        let formatter = HumanFormatter::new(false);
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency",
        )
        .with_related(Span::line("config.yml", 5), "step_a defined here")];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("= note: step_a defined here"));
        assert!(output.contains("config.yml:5"));
    }

    #[test]
    fn no_summary_when_no_issues() {
        let formatter = HumanFormatter::new(false);
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("Found"));
    }
}

//! CLI argument definitions.
//!
//! This module defines all CLI arguments using clap's derive macros.
//! The main entry point is the [`Cli`] struct.

use clap::{Parser, Subcommand};
use clap_complete::Shell;
use std::path::PathBuf;

/// Bivvy - Development environment setup automation.
#[derive(Debug, Parser)]
#[command(name = "bivvy")]
#[command(author, version, about, long_about = None)]
#[command(propagate_version = true)]
pub struct Cli {
    /// Path to config file (overrides default .bivvy/config.yml)
    #[arg(short, long, global = true)]
    pub config: Option<PathBuf>,

    /// Path to project root (overrides current directory)
    #[arg(short, long, global = true)]
    pub project: Option<PathBuf>,

    /// Show verbose output
    #[arg(short, long, global = true)]
    pub verbose: bool,

    /// Minimal output
    #[arg(short, long, global = true)]
    pub quiet: bool,

    /// Disable colored output
    #[arg(long, global = true)]
    pub no_color: bool,

    /// Enable debug logging
    #[arg(long, global = true)]
    pub debug: bool,

    #[command(subcommand)]
    pub command: Option<Commands>,
}

use super::commands::cache::CacheArgs;
use super::commands::feedback::FeedbackArgs;

/// Available subcommands.
#[derive(Debug, Subcommand)]
pub enum Commands {
    /// Run setup workflow (default if no command specified)
    Run(RunArgs),

    /// Initialize Bivvy configuration for a project
    Init(InitArgs),

    /// Show current setup status
    Status(StatusArgs),

    /// List available steps and workflows
    List(ListArgs),

    /// Show last run information
    Last(LastArgs),

    /// Show execution history
    History(HistoryArgs),

    /// Validate configuration files
    Lint(LintArgs),

    /// Show resolved configuration
    Config(ConfigArgs),

    /// Manage template cache
    Cache(CacheArgs),

    /// Capture and manage feedback
    Feedback(FeedbackArgs),

    /// Generate shell completions
    Completions(CompletionsArgs),
}

/// Arguments for the `run` command.
#[derive(Debug, Clone, clap::Args)]
pub struct RunArgs {
    /// Workflow to run
    #[arg(short, long, default_value = "default")]
    pub workflow: String,

    /// Run only specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub only: Vec<String>,

    /// Skip specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub skip: Vec<String>,

    /// How to handle skipped step dependencies
    #[arg(long, default_value = "skip_with_dependents")]
    pub skip_behavior: String,

    /// Force re-run of specified steps (comma-separated)
    #[arg(short, long, value_delimiter = ',')]
    pub force: Vec<String>,

    /// Resume an interrupted run
    #[arg(long)]
    pub resume: bool,

    /// Save prompt answers for future runs
    #[arg(long)]
    pub save_preferences: bool,

    /// Preview commands without executing
    #[arg(long)]
    pub dry_run: bool,

    /// Use defaults, no prompts
    #[arg(long)]
    pub non_interactive: bool,

    /// Deprecated: use --non-interactive and --env ci instead
    #[arg(long, hide = true)]
    pub ci: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

impl Default for RunArgs {
    fn default() -> Self {
        Self {
            workflow: "default".to_string(),
            only: Vec::new(),
            skip: Vec::new(),
            skip_behavior: "skip_with_dependents".to_string(),
            force: Vec::new(),
            resume: false,
            save_preferences: false,
            dry_run: false,
            non_interactive: false,
            ci: false,
            env: None,
        }
    }
}

/// Arguments for the `init` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct InitArgs {
    /// Generate minimal config without prompts
    #[arg(long)]
    pub minimal: bool,

    /// Start from a specific template
    #[arg(long)]
    pub template: Option<String>,

    /// Copy configuration from another project
    #[arg(long)]
    pub from: Option<String>,

    /// Overwrite existing configuration
    #[arg(long)]
    pub force: bool,
}

/// Arguments for the `status` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct StatusArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show status for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `list` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ListArgs {
    /// List only steps
    #[arg(long)]
    pub steps_only: bool,

    /// List only workflows
    #[arg(long)]
    pub workflows_only: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `last` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LastArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show details for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Show all runs
    #[arg(long)]
    pub all: bool,

    /// Include command output
    #[arg(long)]
    pub output: bool,
}

/// Arguments for the `history` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct HistoryArgs {
    /// Filter by step name
    #[arg(long)]
    pub step: Option<String>,

    /// Number of runs to show
    #[arg(long)]
    pub limit: Option<usize>,

    /// Show runs since duration (e.g., "1h", "7d", "30m")
    #[arg(long)]
    pub since: Option<String>,

    /// Show detailed view with steps for each run
    #[arg(long)]
    pub detail: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,
}

/// Arguments for the `lint` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LintArgs {
    /// Output format: human, json, sarif
    #[arg(long, default_value = "human")]
    pub format: String,

    /// Auto-fix simple issues
    #[arg(long)]
    pub fix: bool,

    /// Treat warnings as errors
    #[arg(long)]
    pub strict: bool,
}

/// Arguments for the `config` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ConfigArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Output as YAML
    #[arg(long)]
    pub yaml: bool,

    /// Show fully merged config
    #[arg(long)]
    pub merged: bool,
}

/// Arguments for the `completions` command.
#[derive(Debug, Clone, clap::Args)]
pub struct CompletionsArgs {
    /// Shell to generate completions for
    #[arg(value_enum)]
    pub shell: Shell,
}

