 1→//! Source location spans.
 2→//!
 3→//! This module provides types for tracking source locations
 4→//! in configuration files, enabling precise error reporting.
 5→
 6→use std::path::PathBuf;
 7→
 8→/// A source location span representing a range in a file.
 9→#[derive(Debug, Clone)]
10→pub struct Span {
11→    /// File path.
12→    pub file: PathBuf,
13→    /// Starting line (1-indexed).
14→    pub start_line: usize,
15→    /// Starting column (1-indexed).
16→    pub start_col: usize,
17→    /// Ending line (1-indexed).
18→    pub end_line: usize,
19→    /// Ending column (1-indexed).
20→    pub end_col: usize,
21→}
22→
23→impl Span {
24→    /// Create a span covering a single line.
25→    pub fn line(file: impl Into<PathBuf>, line: usize) -> Self {
26→        Self {
27→            file: file.into(),
28→            start_line: line,
29→            start_col: 1,
30→            end_line: line,
31→            end_col: usize::MAX,
32→        }
33→    }
34→
35→    /// Create a span with precise positions.
36→    pub fn new(
37→        file: impl Into<PathBuf>,
38→        start_line: usize,
39→        start_col: usize,
40→        end_line: usize,
41→        end_col: usize,
42→    ) -> Self {
43→        Self {
44→            file: file.into(),
45→            start_line,
46→            start_col,
47→            end_line,
48→            end_col,
49→        }
50→    }
51→}
52→
