```rust
//! GitHub Actions output formatter.
//!
//! Emits [workflow commands] so that lint diagnostics appear as inline
//! annotations in GitHub Actions CI runs.
//!
//! [workflow commands]: https://docs.github.com/en/actions/using-workflows/workflow-commands-for-github-actions

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic produces a single line:
///
/// ```text
/// ::error file=config.yml,line=10,col=5,title=rule-id::message text
/// ```
///
/// Severity mapping:
/// - [`Severity::Error`] -> `::error::`
/// - [`Severity::Warning`] -> `::warning::`
/// - [`Severity::Hint`] -> `::notice::`
pub struct GithubFormatter;

impl GithubFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_to_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GithubFormatter {
    fn default() -> Self {
        Self::new()
    }
}

/// Escape a value for use in a workflow command property.
///
/// Properties require escaping: `%` -> `%25`, `\r` -> `%0D`,
/// `\n` -> `%0A`, `:` -> `%3A`, `,` -> `%2C`.
fn escape_property(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
        .replace(':', "%3A")
        .replace(',', "%2C")
}

/// Escape a value for use in a workflow command message.
///
/// Messages require escaping: `%` -> `%25`, `\r` -> `%0D`,
/// `\n` -> `%0A`.
fn escape_message(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

impl LintFormatter for GithubFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_to_command(diag.severity);

            // Build properties
            let mut props = Vec::new();

            if let Some(ref span) = diag.span {
                props.push(format!("file={}", escape_property(&span.file.display().to_string())));
                props.push(format!("line={}", span.start_line));
                props.push(format!("col={}", span.start_col));

                // Only include endLine if it differs from start_line,
                // or if we have a meaningful endColumn.
                let has_meaningful_end_col = span.end_col != usize::MAX;
                if span.end_line != span.start_line || has_meaningful_end_col {
                    props.push(format!("endLine={}", span.end_line));
                }
                if has_meaningful_end_col {
                    props.push(format!("endColumn={}", span.end_col));
                }
            }

            props.push(format!("title={}", escape_property(&diag.rule_id.0)));

            // Build message
            let mut message = escape_message(&diag.message);
            if let Some(ref suggestion) = diag.suggestion {
                message.push_str("%0ASuggestion: ");
                message.push_str(&escape_message(suggestion));
            }

            // Write the workflow command
            writeln!(writer, "::{} {}::{}", command, props.join(","), message)?;
        }

        Ok(())
    }
}
```

The `%` replacement must come first in both escape functions to avoid double-escaping.

